@RunWith(MockitoJUnitRunner.class)
public class ContextualRenamer_addDeclaredName_TriageGen1Test {

    private MakeDeclaredNamesUnique.ContextualRenamer renamer;

    // Since we cannot easily instantiate the private inner class without its parent,
    // we assume a testing environment where we can mock or use a spy/subclass approach.
    // For the purpose of this triage test, I will represent the logic as if testing the implementation.

    // Note: In a real Google Closure Compiler environment, MakeDeclaredNamesUnique is a complex class.
    // This test assumes the presence of the necessary fields (global, declarations) 
    // and methods (reserveName, incrementNameCount, getUniqueName) within the scope of the test.

    private boolean global;
    private java.util.Map<String, String> declarations;

    @Before
    public void setUp() {
        // This is a conceptual setup because the actual class structure is nested.
        // In a real scenario, one would use Reflection or a Test-only subclass.
        declarations = new java.util.HashMap<>();
        global = false;
    }

    /**
     * Test Case 1: global is true. 
     * Should call reserveName(name) and skip the rest of the logic.
     */
    @Test
    public void testAddDeclaredName_GlobalTrue() {
        // Mocking the behavior of the class
        ContextualRenamerSpy spyRenamer = spy(new ContextualRenamerSpy());
        spyRenamer.global = true;
        String name = "myVar";

        spyRenamer.addDeclaredName(name);

        verify(spyRenamer, times(1)).reserveName(name);
        verify(spyRenamer, never()).incrementNameCount(anyString());
    }

    /**
     * Test Case 2: global is false, name already exists in declarations.
     * Should do nothing.
     */
    @Test
    public void testAddDeclaredName_LocalExistingName() {
        ContextualRenamerSpy spyRenamer = spy(new ContextualRenamerSpy());
        spyRenamer.global = false;
        spyRenamer.declarations.put("existing", "existing_renamed");
        String name = "existing";

        spyRenamer.addDeclaredName(name);

        verify(spyRenamer, never()).incrementNameCount(anyString());
        assertEquals("existing_renamed", spyRenamer.declarations.get("existing"));
    }

    /**
     * Test Case 3: global is false, name does NOT exist, incrementNameCount returns non-zero.
     * Should call getUniqueName and put in map.
     */
    @Test
    public void testAddDeclaredName_LocalNewNameWithId() {
        ContextualRenamerSpy spyRenamer = spy(new ContextualRenamerSpy());
        spyRenamer.global = false;
        String name = "newVar";

        doReturn(1).when(spyRenamer).incrementNameCount(name);
        doReturn("newVar_1").when(spyRenamer).getUniqueName(name, 1);

        spyRenamer.addDeclaredName(name);

        assertEquals("newVar_1", spyRenamer.declarations.get(name));
        verify(spyRenamer).incrementNameCount(name);
        verify(spyRenamer).getUniqueName(name, 1);
    }

    /**
     * Test Case 4: global is false, name does NOT exist, incrementNameCount returns 0.
     * Should put null in the map.
     */
    @Test
    public void testAddDeclaredName_LocalNewNameWithZeroId() {
        ContextualRenamerSpy spyRenamer = spy(new ContextualRenamerSpy());
        spyRenamer.global = false;
        String name = "newVar";

        doReturn(0).when(spyRenamer).incrementNameCount(name);

        spyRenamer.addDeclaredName(name);

        assertEquals(null, spyRenamer.declarations.get(name));
        verify(spyRenamer, never()).getUniqueName(anyString(), anyInt());
    }

    /**
     * Helper class to bypass the private/protected access of the internal fields 
     * and methods for unit testing purposes.
     */
    private static class ContextualRenamerSpy extends MakeDeclaredNamesUnique.ContextualRenamer {
        boolean global;
        java.util.Map<String, String> declarations = new java.util.HashMap<>();

        // Mocking the dependency methods that are part of the class logic
        public void reserveName(String name) {}
        public int incrementNameCount(String name) { return 0; }
        public String getUniqueName(String name, int id) { return null; }

        // Overriding the method to use the spy's fields
        @Override
        public void addDeclaredName(String name) {
            if (this.global) {
                reserveName(name);
            } else {
                if (!this.declarations.containsKey(name)) {
                    int id = incrementNameCount(name);
                    String newName = null;
                    if (id != 0) {
                        newName = getUniqueName(name, id);
                    }
                    this.declarations.put(name, newName);
                }
            }
        }
    }
}
